INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Switches für ein kleines Unternehmen entscheidend?', 2, '[{"text": "Anzahl der Ports", "correct": true, "because": "Bestimmt die Anschlussmöglichkeiten"}, {"text": "Farbe des Geräts", "correct": false, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Switch dasselbe wie ein Router?', 1, '[{"text": "Nein", "correct": true, "because": "Switch verbindet Geräte, Router leitet Daten"}, {"text": "Ja", "correct": false, "because": "Funktionen unterscheiden sich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die Leistung eines Switches wichtig?', 5, '[{"text": "Datenrate (Gigabit)", "correct": true, "because": "Bestimmt Übertragungsgeschwindigkeit"}, {"text": "Anzahl der Ports", "correct": true, "because": "Beeinflusst Kapazität"}, {"text": "Gewicht des Geräts", "correct": false, "because": "Kein Einfluss auf Leistung"}, {"text": "Managed-Funktionen", "correct": true, "because": "Ermöglicht Netzwerksteuerung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Switches richtig? a) Ein Switch kann WLAN bereitstellen. b) Ein Switch verbindet Geräte im selben Netzwerk.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Switches haben kein WLAN"}, {"text": "Nur b) stimmt", "correct": true, "because": "Switches verbinden lokal"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist falsch"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist wahr"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines Switches für ein Heimnetzwerk ignorieren?', 2, '[{"text": "QoS-Funktionen", "correct": false, "because": "Wichtig für Priorisierung"}, {"text": "Design des Gehäuses", "correct": true, "because": "Kein Einfluss auf Funktion"}, {"text": "Portgeschwindigkeit", "correct": false, "because": "Entscheidend für Leistung"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Switches für ein kleines Unternehmen entscheidend?', 2, '[{"text": "Anzahl der Ports", "correct": true, "because": "Bestimmt die Anzahl an Geräten"}, {"text": "Farbe des Gehäuses", "correct": false, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Switch in der Lage, Daten zwischen verschiedenen Netzwerken zu leiten?', 1, '[{"text": "Nein", "correct": true, "because": "Switches arbeiten nur innerhalb eines Netzwerks"}, {"text": "Ja", "correct": false, "because": "Routing ist Aufgabe eines Routers"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die Leistung eines Switches wichtig?', 5, '[{"text": "Übertragungsrate", "correct": true, "because": "Bestimmt die Datenbandbreite"}, {"text": "Managed-Funktionen", "correct": true, "because": "Ermöglicht Netzwerksteuerung"}, {"text": "Gewicht des Geräts", "correct": false, "because": "Kein Einfluss auf Leistung"}, {"text": "Anzahl der Ports", "correct": true, "because": "Beeinflusst die Kapazität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Switches richtig? a) Ein Switch verbessert die Netzwerkgeschwindigkeit. b) Ein Switch benötigt eine Internetverbindung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Switch optimiert Datenfluss lokal"}, {"text": "Beides stimmt", "correct": false, "because": "Internet ist nicht nötig"}, {"text": "Nur b) stimmt", "correct": false, "because": "Switch arbeitet lokal"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines Switches für ein Heimnetzwerk ignorieren?', 2, '[{"text": "Anzahl der Ports", "correct": false, "because": "Wichtig für Geräteanzahl"}, {"text": "Optisches Design", "correct": true, "because": "Kein Einfluss auf Funktion"}, {"text": "Gigabit-Unterstützung", "correct": false, "because": "Relevant für Geschwindigkeit"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Switches für ein Großraumbüro entscheidend?', 2, '[{"text": "Anzahl der Ports", "correct": true, "because": "Bestimmt die Anschlusskapazität"}, {"text": "Design des Gehäuses", "correct": false, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Switch in der Lage, Daten zwischen verschiedenen Netzwerken zu leiten?', 1, '[{"text": "Nein", "correct": true, "because": "Das macht ein Router"}, {"text": "Ja", "correct": false, "because": "Switch arbeitet nur im gleichen Netzwerk"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die Leistung eines Switches entscheidend?', 5, '[{"text": "Übertragungsrate (z.B. Gigabit)", "correct": true, "because": "Bestimmt die Geschwindigkeit"}, {"text": "Anzahl der Ports", "correct": true, "because": "Erhöht die Kapazität"}, {"text": "Farbe des Geräts", "correct": false, "because": "Kein Einfluss"}, {"text": "QoS-Unterstützung", "correct": true, "because": "Priorisiert Datenverkehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Switches richtig? a) Ein unmanaged Switch benötigt keine Konfiguration. b) Ein Switch verbindet verschiedene Subnetze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unmanaged Switches sind Plug-and-Play"}, {"text": "Beides stimmt", "correct": false, "because": "Subnetze verbindet ein Router"}, {"text": "Nur b) stimmt", "correct": false, "because": "Switches arbeiten in einem Netz"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines Switches für ein Heimnetzwerk ignorieren?', 2, '[{"text": "PoE-Funktion", "correct": true, "because": "Nur für spezielle Geräte nötig"}, {"text": "Portanzahl", "correct": false, "because": "Wichtig für Anschlüsse"}, {"text": "Datenrate", "correct": false, "because": "Entscheidend für Geschwindigkeit"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Switches für ein Büro entscheidend?', 2, '[{"text": "Portanzahl", "correct": true, "because": "Bestimmt die Anschlussmöglichkeiten"}, {"text": "Gehäusefarbe", "correct": false, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Switch für die Verbindung verschiedener Subnetze geeignet?', 1, '[{"text": "Nein", "correct": true, "because": "Switches arbeiten in einem Netzwerk"}, {"text": "Ja", "correct": false, "because": "Routing ist nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die Leistung eines Switches wichtig?', 5, '[{"text": "Datenrate (Gigabit)", "correct": true, "because": "Beeinflusst Geschwindigkeit"}, {"text": "Portanzahl", "correct": true, "because": "Erhöht Kapazität"}, {"text": "Gewicht des Geräts", "correct": false, "because": "Kein Einfluss"}, {"text": "VLAN-Unterstützung", "correct": true, "because": "Trennt Netzwerke logisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Switches richtig? a) Ein Switch kann Daten priorisieren. b) Ein Switch verbindet verschiedene Netzwerke.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "QoS ermöglicht Priorisierung"}, {"text": "Beides stimmt", "correct": false, "because": "Netzwerkverbindung ist Router-Aufgabe"}, {"text": "Nur b) stimmt", "correct": false, "because": "Switches sind lokal"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines Switches für ein kleines LAN ignorieren?', 2, '[{"text": "Datenrate", "correct": false, "because": "Wichtig für Leistung"}, {"text": "Optisches Design", "correct": true, "because": "Kein Einfluss auf Funktion"}, {"text": "PoE-Funktion", "correct": false, "because": "Kann nützlich sein"}]');
